			function onGrdListRowDblclick( /* cpr.events.CGridMouseEvent */ e) {
			    
			    var grdList       = e.control;
			    
			    if(boDtlUser){
			        var vnRowData     = grdList.getSelectedRow().getRowData();
			    
			        var detailUrl     = "app/itgcm/casemng/uneart/emrgIntrvnInsert";
			        var detailTitle   = "긴급구조상세";
			    
			        // 재조회를 위한 상담번호를 반환
			        var vsDscsnNo = grdList.getCellValue(grdList.getSelectedRowIndex(), "DSCSN_NO");
			        
			        util.openMainMenu(app, detailUrl, detailTitle, function( /*cpr.controls.EmbeddedApp*/ pcEmb) {
			            if (typeof pcEmb.isFloated == "function") {
			                pcEmb.ready(function() {
			                    pcEmb.setAppProperties({
			                        "type" : "READ",
			                        "data": vnRowData,
			                        "btnUseYn" : btnUseVal                     
			                    });
			                })
			            } else {
			                pcEmb.setAppProperties({
			                    "type" : "READ",
			                    "data": vnRowData,
			                    "btnUseYn" : btnUseVal                     
			                });
			            }
			        });
			    }else{
			        util.Msg.alert(app, "상세보기 권한이 없습니다.");
			        return;         
			    }
			}

